export const MINIMAX_VOICE_BY_ID = new Map(
  MINIMAX_SYSTEM_VOICES.map((voice) => [voice.voiceId, voice]),
);

export function normalizeVoiceSearch(value) {
  return String(value ?? "")
    .normalize("NFKC")
    .toLocaleLowerCase()
    .replace(/\s+/gu, " ")
    .trim();
}

export function filterMiniMaxVoices(query, voices = MINIMAX_SYSTEM_VOICES) {
  const terms = normalizeVoiceSearch(query).split(" ").filter(Boolean);
  if (terms.length === 0) {
    return Array.from(voices);
  }
  return voices.filter((voice) => {
    const haystack = normalizeVoiceSearch(
      `${voice.language} ${voice.name} ${voice.voiceId}`,
    );
    return terms.every((term) => haystack.includes(term));
  });
}

export function formatMiniMaxVoiceLabel(voice) {
  return voice?.display || `${voice?.name ?? ""}（${voice?.voiceId ?? ""}）`;
}
